 end loop;
 if (select jsonb_agg(t order by jobid) from (select jobid,jobname,schedule,command,active,database,username from cron.job)t) is distinct from '[{"jobid":1,"active":true,"command":"select public.cleanup_expired_anonymous_onboarding();","jobname":"anonymous-onboarding-cleanup-daily","database":"postgres","schedule":"0 18 * * *","username":"postgres"},{"jobid":2,"active":true,"command":"select public.finalize_daily_ranking_rewards();","jobname":"daily-ranking-reward-finalize-jst-midnight","database":"postgres","schedule":"0 15 * * *","username":"postgres"},{"jobid":3,"active":true,"command":"select public.finalize_preopen_guild_power_season();","jobname":"preopen-guild-power-finalize-20260909-jst","database":"postgres","schedule":"* 15 8 9 *","username":"postgres"},{"jobid":4,"active":true,"command":"select public.advance_ranking_season(''PVP'',clock_timestamp());","jobname":"ranking-pvp-monthly-jst","database":"postgres","schedule":"0 15 * * *","username":"postgres"},{"jobid":5,"active":true,"command":"select public.advance_ranking_season(''RAID'',clock_timestamp());","jobname":"ranking-raid-weekly-jst","database":"postgres","schedule":"0 15 * * 0","username":"postgres"},{"jobid":9,"active":true,"command":"set statement_timeout=''120s''; select public.refresh_kpi_overview_saved_results();","jobname":"kpi-overview-saved-results-half-hourly","database":"postgres","schedule":"7,37 * * * *","username":"postgres"}]'::jsonb then raise exception 'existing Cron changed'; end if;
 if (select jsonb_agg(t order by version) from (select version,name from supabase_migrations.schema_migrations)t) is distinct from '[{"name":"preopen_production_snapshot_baseline","version":"20260904000241"},{"name":"production_daily_activity_schema_parity","version":"20260904000242"},{"name":"kpi_measurement_fact_foundation","version":"20260904000243"},{"name":"kpi_measurement_lifecycle_hooks","version":"20260904000244"},{"name":"kpi_snapshot_foundation","version":"20260904000245"},{"name":"kpi_snapshot_refresh_rpcs","version":"20260904000246"},{"name":"kpi_measurement_security","version":"20260904000247"},{"name":"kpi_timeseries_dashboard","version":"20260905000248"},{"name":"kpi_authority_extensions","version":"20260906000249"},{"name":"acquisition_attribution_landing_authority","version":"20260907000250"},{"name":"world_intro_journey_events","version":"20260907000251"},{"name":"kpi_overview_saved_results","version":"20260908042558"},{"name":"quest_cash_retention_hotfix_20260909","version":"20260908162650"},{"name":"pvp_opponents_power_multiply_bigint","version":"20260909003245"},{"name":"acquisition_subject_first_touch_phase1","version":"20260909140811"},{"name":"acquisition_source_saved_results_phase1","version":"20260909140820"},{"name":"acquisition_guild_cohort_denominator","version":"20260909140828"},{"name":"kpi_social_active_raid_point_daily","version":"20260909151723"}]'::jsonb then raise exception 'migration history changed'; end if;
 if exists(select 1 from public.raid_room_creation_settings where enabled) or exists(select 1 from public.raid_room_battle_settings where enabled) or exists(select 1 from public.raid_room_rescue_settings where enabled) then raise exception 'Room unexpectedly enabled'; end if;
 if not exists(select 1 from public.raid_legacy_settings where singleton and enabled) then raise exception 'legacy flag changed'; end if;
 if exists(select 1 from public.raid_room_clear_reward_rules where enabled) or exists(select 1 from public.raid_room_rescue_reward_rules where enabled) then raise exception 'reward unexpectedly enabled'; end if;
 if (select count(*) from pg_class where relnamespace='public'::regnamespace and relname like 'raid_room%' and relkind='r' and not relrowsecurity)>0 then raise exception 'Room RLS missing'; end if;
end $verify$;
