) loop
  select jsonb_build_object('owner',pg_get_userbyid(p.proowner),'acl',p.proacl) into actual from pg_proc p where p.pronamespace='public'::regnamespace and p.proname=r.name and pg_get_function_identity_arguments(p.oid)=r.args;
  if actual is distinct from jsonb_build_object('owner',r.owner,'acl',r.acl) then raise exception 'existing function owner/ACL changed: % (%)',r.name,r.args; end if;
 end loop;
end $preserve_catalog$;

do $kpi$ begin if not exists(select from pg_proc where oid=to_regprocedure('public.kpi_daily_engagement_v1(date,date)') and md5(pg_get_functiondef(oid))='e5da97325d85412cccc4d894e57140be' and proacl::text='{postgres=X/postgres}') then raise exception 'KPI daily function changed';end if;end $kpi$;
